DELETE FROM "airtable"."events" as d WHERE EXISTS (SELECT 1 FROM "airtable_staging"."events" as s WHERE d."id" = s."id")
INSERT INTO "airtable"."events"("id", "created_time", "fields__description", "fields__check_in_url", "fields__qr_code", "fields__event_status", "fields__event_id", "fields__name", "fields__created_by__id", "fields__created_by__email", "fields__created_by__name", "_dlt_load_id", "_dlt_id", "fields__event_date", "fields__location")                  SELECT "id", "created_time", "fields__description", "fields__check_in_url", "fields__qr_code", "fields__event_status", "fields__event_id", "fields__name", "fields__created_by__id", "fields__created_by__email", "fields__created_by__name", "_dlt_load_id", "_dlt_id", "fields__event_date", "fields__location"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "id", "created_time", "fields__description", "fields__check_in_url", "fields__qr_code", "fields__event_status", "fields__event_id", "fields__name", "fields__created_by__id", "fields__created_by__email", "fields__created_by__name", "_dlt_load_id", "_dlt_id", "fields__event_date", "fields__location"                         FROM "airtable_staging"."events"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND (1 = 1)          